-- Squashed from 5 prior migrations (see git log) on 2026-05-04.
-- App: spreadsheet. Generated by scripts/phase4-squash-app.mjs from a
-- pg_dump --schema-only of a freshly-migrated flagship_spreadsheet DB.
--
-- This is a hand-derived baseline migration: it captures the verified-
-- green schema produced by the prior multi-file migration set, in a
-- single replayable file. `mlcl create <app>` will scaffold this as
-- migration 0010 and the runtime migration runner will apply it as a
-- single transaction at first boot.
CREATE TABLE public.automations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    spreadsheet_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    name text NOT NULL,
    trigger jsonb DEFAULT '{}'::jsonb NOT NULL,
    action jsonb DEFAULT '{}'::jsonb NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    last_run_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: chart_definitions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.chart_definitions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sheet_id uuid NOT NULL,
    spreadsheet_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    name text NOT NULL,
    type text DEFAULT 'bar'::text NOT NULL,
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


